/// Live Windows `Font.body` profile resolved from current DPI-aware system
/// message-font settings. Runtime clients pass returned values through existing
/// text measurement APIs; no Apple-specific target metrics are embedded here.
public struct NativeWindowsBodyFont: Equatable, Sendable {
    public let family: String
    public let fontSizeDIP: Float
    public let lineHeightDIP: Float
    public let weight: UInt32
    public let logFontHeight: Int32
    public let textMetricHeight: Int32
    public let textMetricAscent: Int32
    public let textMetricDescent: Int32
    public let textMetricExternalLeading: Int32
    public let dpi: UInt32
    public let sourceAPI: String

    public init(family: String, fontSizeDIP: Float, lineHeightDIP: Float,
                weight: UInt32, logFontHeight: Int32,
                textMetricHeight: Int32, textMetricAscent: Int32,
                textMetricDescent: Int32, textMetricExternalLeading: Int32,
                dpi: UInt32, sourceAPI: String) {
        self.family = family
        self.fontSizeDIP = fontSizeDIP
        self.lineHeightDIP = lineHeightDIP
        self.weight = weight
        self.logFontHeight = logFontHeight
        self.textMetricHeight = textMetricHeight
        self.textMetricAscent = textMetricAscent
        self.textMetricDescent = textMetricDescent
        self.textMetricExternalLeading = textMetricExternalLeading
        self.dpi = dpi
        self.sourceAPI = sourceAPI
    }
}

public enum NativeWindowsBodyFontError: Error, Equatable {
    case invalidDPI
    case systemParametersUnavailable
    case invalidMessageFont
    case deviceContextUnavailable
    case fontUnavailable
    case fontSelectionUnavailable
    case selectedFaceUnavailable
    case textMetricsUnavailable
    case invalidMetrics
    case windowsOnly
}

/// Resolves live Windows default body-font metadata. Resolution is isolated in
/// runtime so every host uses same profile policy & retains real font identity.
public enum NativeWindowsBodyFontResolver {
    public static func resolve(dpi: UInt32, emitLog: Bool = true) throws -> NativeWindowsBodyFont {
        guard dpi >= 48, dpi <= 768 else { throw NativeWindowsBodyFontError.invalidDPI }
#if os(Windows)
        let scale = Float(dpi) / 96
        var nonClient = NONCLIENTMETRICSW()
        let nonClientSize = UInt32(MemoryLayout<NONCLIENTMETRICSW>.size)
        nonClient.cbSize = nonClientSize
        let parametersOK = withUnsafeMutablePointer(to: &nonClient) { pointer in
            SystemParametersInfoForDpi(UInt32(0x0029), nonClientSize,
                                       UnsafeMutableRawPointer(pointer), UInt32(0), dpi)
        }
        guard parametersOK else { throw NativeWindowsBodyFontError.systemParametersUnavailable }

        var logFont = nonClient.lfMessageFont
        let rawHeight = Int64(logFont.lfHeight)
        guard rawHeight != 0 else { throw NativeWindowsBodyFontError.invalidMessageFont }
        let fontHeightPixels = abs(rawHeight)
        guard let dc = CreateCompatibleDC(nil) else {
            throw NativeWindowsBodyFontError.deviceContextUnavailable
        }
        defer { _ = DeleteDC(dc) }
        guard let font = withUnsafePointer(to: &logFont, { CreateFontIndirectW($0) }) else {
            throw NativeWindowsBodyFontError.fontUnavailable
        }
        defer { _ = DeleteObject(font) }
        guard let previous = SelectObject(dc, font) else {
            throw NativeWindowsBodyFontError.fontSelectionUnavailable
        }
        defer { _ = SelectObject(dc, previous) }

        var faceBuffer = [WCHAR](repeating: 0, count: 256)
        let faceLength = faceBuffer.withUnsafeMutableBufferPointer { buffer -> Int32 in
            GetTextFaceW(dc, Int32(buffer.count), buffer.baseAddress)
        }
        guard faceLength > 0, faceLength < Int32(faceBuffer.count) else {
            throw NativeWindowsBodyFontError.selectedFaceUnavailable
        }
        let selectedFace = String(decoding: faceBuffer.prefix(Int(faceLength)).prefix(while: { $0 != 0 }), as: UTF16.self)
        guard !selectedFace.isEmpty else { throw NativeWindowsBodyFontError.selectedFaceUnavailable }

        var textMetrics = TEXTMETRICW()
        guard GetTextMetricsW(dc, &textMetrics) else {
            throw NativeWindowsBodyFontError.textMetricsUnavailable
        }
        guard textMetrics.tmHeight > 0, textMetrics.tmAscent >= 0, textMetrics.tmDescent >= 0 else {
            throw NativeWindowsBodyFontError.invalidMetrics
        }
        let fontSizeDIP = Float(fontHeightPixels) / scale
        let lineHeightDIP = Float(textMetrics.tmHeight) / scale
        guard fontSizeDIP.isFinite, fontSizeDIP > 0,
              lineHeightDIP.isFinite, lineHeightDIP > 0 else {
            throw NativeWindowsBodyFontError.invalidMetrics
        }
        let weight = UInt32(max(0, min(Int64(logFont.lfWeight), Int64(UInt32.max))))
        let sourceAPI = "SystemParametersInfoForDpi(SPI_GETNONCLIENTMETRICS)+CreateFontIndirectW+GetTextMetricsW"
        if emitLog {
            print("FACTORY_BODY_FONT_POLICY api=\(sourceAPI) family=\(selectedFace) dpi=\(dpi) lfHeight=\(logFont.lfHeight) fontSizeDIP=\(fontSizeDIP) tmHeightPX=\(textMetrics.tmHeight) tmAscentPX=\(textMetrics.tmAscent) tmDescentPX=\(textMetrics.tmDescent) tmExternalLeadingPX=\(textMetrics.tmExternalLeading) lineHeightDIP=\(lineHeightDIP) weight=\(weight) scale=\(scale)")
        }
        return NativeWindowsBodyFont(family: selectedFace, fontSizeDIP: fontSizeDIP,
                                     lineHeightDIP: lineHeightDIP, weight: weight,
                                     logFontHeight: logFont.lfHeight,
                                     textMetricHeight: textMetrics.tmHeight,
                                     textMetricAscent: textMetrics.tmAscent,
                                     textMetricDescent: textMetrics.tmDescent,
                                     textMetricExternalLeading: textMetrics.tmExternalLeading,
                                     dpi: dpi, sourceAPI: sourceAPI)
#else
        _ = emitLog
        throw NativeWindowsBodyFontError.windowsOnly
#endif
    }
}

import Foundation

/// One public-path-compatible element for SwiftUI continuous rounded corners.
public enum ContinuousPathElement: Equatable, Sendable {
    case move(to: LayoutPoint)
    case line(to: LayoutPoint)
    case cubic(to: LayoutPoint, control1: LayoutPoint, control2: LayoutPoint)
    case close
}

/// Explicit rejection prevents unsupported large-radius requests from being
/// silently replaced by circular or fixture-specific geometry.
public enum ContinuousRoundedGeometryError: Error, Equatable, Sendable {
    case invalidBounds
    case unsupportedRadiusExtent
}

/// Generic continuous-corner geometry derived from public SwiftUI
/// `RoundedRectangle.path(in:)` output. Coefficients are scale-free, so no
/// witness dimensions or pixel fixture are embedded.
public enum ContinuousRoundedGeometry {
    // Four path probes produced same normalized coefficients across aspect
    // ratios 2:1, 105:55, 1:1, & 3:1. Constants describe Apple's three-cubic
    // smooth corner family rather than circular or superellipse substitution.
    private static let extent = 1.528664946556
    private static let endpointNear = 0.074911400676
    private static let endpointFar = 0.631493985653
    private static let controlOuter = 1.088490009308
    private static let controlInner = 0.868407011032
    private static let controlMiddleNear = 0.169060006738
    private static let controlMiddleFar = 0.372824013233

    public static func path(in rect: LayoutRect, cornerRadius: CGFloat) throws -> [ContinuousPathElement] {
        let x0 = Double(rect.minX), y0 = Double(rect.minY)
        let width = max(0, Double(rect.width)), height = max(0, Double(rect.height))
        guard width.isFinite, height.isFinite, width > 0, height > 0 else {
            throw ContinuousRoundedGeometryError.invalidBounds
        }
        guard cornerRadius.isFinite, cornerRadius >= 0 else {
            throw ContinuousRoundedGeometryError.invalidBounds
        }
        let requested = Double(cornerRadius)
        // R2 shows Apple clamps path extent independently from requested
        // radius for large requests, then adjusts control points. Reusing
        // ordinary-radius coefficients after clamping radius is incorrect.
        // Reject until independently observed large-radius coefficients exist.
        let maxSupportedRadius = min(width, height) / (2 * extent)
        guard requested <= maxSupportedRadius + 0.000001 else {
            throw ContinuousRoundedGeometryError.unsupportedRadiusExtent
        }
        if requested == 0 {
            let x1 = x0 + width, y1 = y0 + height
            func p(_ x: Double, _ y: Double) -> LayoutPoint {
                LayoutPoint(x: CGFloat(x), y: CGFloat(y))
            }
            return [.move(to: p(x0, y0)), .line(to: p(x1, y0)),
                    .line(to: p(x1, y1)), .line(to: p(x0, y1)), .close]
        }
        let radius = requested
        let e = radius * extent
        let a = radius * endpointNear
        let b = radius * endpointFar
        let outer = radius * controlOuter
        let inner = radius * controlInner
        let middleNear = radius * controlMiddleNear
        let middleFar = radius * controlMiddleFar
        let x1 = x0 + width, y1 = y0 + height
        let xm = (x0 + x1) / 2, ym = (y0 + y1) / 2
        let right = x1, left = x0, top = y0, bottom = y1
        var result: [ContinuousPathElement] = []
        result.reserveCapacity(18)
        func p(_ x: Double, _ y: Double) -> LayoutPoint { LayoutPoint(x: CGFloat(x), y: CGFloat(y)) }
        func cubic(_ to: (Double, Double), _ c1: (Double, Double), _ c2: (Double, Double)) {
            result.append(.cubic(to: p(to.0, to.1), control1: p(c1.0, c1.1), control2: p(c2.0, c2.1)))
        }

        result.append(.move(to: p(right, ym)))
        result.append(.line(to: p(right, bottom - e)))
        cubic((right - a, bottom - b), (right, bottom - outer), (right, bottom - inner))
        cubic((right - b, bottom - a), (right - middleNear, bottom - middleFar), (right - middleFar, bottom - middleNear))
        cubic((right - e, bottom), (right - inner, bottom), (right - outer, bottom))
        result.append(.line(to: p(left + e, bottom)))
        cubic((left + a, bottom - b), (left + outer, bottom), (left + inner, bottom))
        cubic((left + b, bottom - a), (left + middleNear, bottom - middleFar), (left + middleFar, bottom - middleNear))
        cubic((left, bottom - e), (left, bottom - inner), (left, bottom - outer))
        result.append(.line(to: p(left, top + e)))
        cubic((left + a, top + b), (left, top + outer), (left, top + inner))
        cubic((left + b, top + a), (left + middleNear, top + middleFar), (left + middleFar, top + middleNear))
        cubic((left + e, top), (left + inner, top), (left + outer, top))
        result.append(.line(to: p(right - e, top)))
        cubic((right - b, top + a), (right - outer, top), (right - inner, top))
        cubic((right - a, top + b), (right - middleFar, top + middleNear), (right - middleNear, top + middleFar))
        cubic((right, top + e), (right, top + inner), (right, top + outer))
        result.append(.close)
        return result
    }
}

import Foundation

// One witness source maps current runtime geometry names to Apple Layout names.
// Windows package keeps runtime LayoutSize/LayoutRect/LayoutPoint; this Mac
// packet keeps same layout algorithm against Apple CGSize/CGRect/CGPoint.
#if os(Windows)
import SwiftRightRuntime
typealias AppleLayout = SwiftRightRuntime.Layout
typealias AppleProposedViewSize = SwiftRightRuntime.ProposedViewSize
typealias AppleLayoutSize = SwiftRightRuntime.LayoutSize
typealias AppleLayoutRect = SwiftRightRuntime.LayoutRect
typealias AppleLayoutPoint = SwiftRightRuntime.LayoutPoint
#else
import SwiftUI
typealias AppleLayout = SwiftUI.Layout
typealias AppleProposedViewSize = SwiftUI.ProposedViewSize
typealias AppleLayoutSize = CGSize
typealias AppleLayoutRect = CGRect
typealias AppleLayoutPoint = CGPoint
#endif

struct Witness_custom_layout: View {
    var body: some View {
        WitnessMeasuredLayout(spacing: 4) {
            ForEach(0..<2, id: \.self) { index in
                Color.red.frame(width: 12 + CGFloat(index) * 4,
                                height: 10 + CGFloat(index) * 4)
            }
        }
        .frame(width: 48, height: 32)
        .environment(\.layoutDirection, .leftToRight)
    }
}

struct WitnessMeasuredLayout: AppleLayout {
    var spacing: CGFloat

    func sizeThatFits(proposal: AppleProposedViewSize,
                      subviews: Subviews,
                      cache: inout ()) -> AppleLayoutSize {
        let sizes = subviews.map { $0.sizeThatFits(.unspecified) }
        let width = sizes.reduce(0) { $0 + $1.width }
            + spacing * CGFloat(max(0, sizes.count - 1))
        let height = sizes.map(\.height).max() ?? 0
        return AppleLayoutSize(width: width, height: height)
    }

    func placeSubviews(in bounds: AppleLayoutRect,
                       proposal: AppleProposedViewSize,
                       subviews: Subviews,
                       cache: inout ()) {
        var x = bounds.minX
        for subview in subviews {
            let size = subview.sizeThatFits(.unspecified)
            subview.place(at: AppleLayoutPoint(x: x, y: bounds.minY),
                          proposal: AppleProposedViewSize(size))
            x += size.width + spacing
        }
    }
}

