3	/// Bounded CPU raster output for a continuous rounded shape. Bytes are RGBA8,
4	/// straight alpha. Coverage uses fixed 4x4 sampling; this is deterministic
5	/// geometry transport for `SWR_PRIM_IMAGE`, not renderer antialias parity.
6	public struct ContinuousRGBAImage: Equatable, Sendable {
7	    public let width: Int
8	    public let height: Int
9	    public let rgba: [UInt8]
10	
11	    public init(width: Int, height: Int, rgba: [UInt8]) {
12	        self.width = width; self.height = height; self.rgba = rgba
13	    }
14	}
15	
16	public enum ContinuousRoundedRasterError: Error, Equatable {
17	    case invalidSize
18	    case invalidStroke
19	    case pixelLimitExceeded
20	    case workLimitExceeded
21	    case unsupportedGeometry
22	}
23	
24	public enum ContinuousRoundedRasterizer {
25	    private static let maxRGBABytes = 16 * 1024 * 1024
26	    private static let maxPixels = maxRGBABytes / 4
27	    private static let maxSampleSegmentEvaluations = 100_000_000
28	    private static let subdivisions = 8
29	
30	    public static func rasterize(width: Int, height: Int, cornerRadius: CGFloat,
31	                                 fillRGBA: UInt32? = nil,
32	                                 strokeRGBA: UInt32? = nil,
33	                                 strokeWidth: CGFloat = 0) throws -> ContinuousRGBAImage {
34	        guard width > 0, height > 0 else { throw ContinuousRoundedRasterError.invalidSize }
35	        guard width <= maxPixels / max(1, height) else { throw ContinuousRoundedRasterError.pixelLimitExceeded }
36	        let stroke = Double(strokeWidth)
37	        guard stroke.isFinite, stroke >= 0 else { throw ContinuousRoundedRasterError.invalidStroke }
38	        guard stroke < Double(min(width, height)) else { throw ContinuousRoundedRasterError.invalidStroke }
39	        let halfStroke = stroke / 2
40	        // Render centered stroke inside output extent. This supplies required
41	        // outer padding instead of clipping half stroke at bitmap edges.
42	        let rect = LayoutRect(x: CGFloat(halfStroke), y: CGFloat(halfStroke),
43	                              width: CGFloat(Double(width) - stroke),
44	                              height: CGFloat(Double(height) - stroke))
45	        let path: [ContinuousPathElement]
46	        do {
47	            path = try ContinuousRoundedGeometry.path(in: rect, cornerRadius: cornerRadius)
48	        } catch ContinuousRoundedGeometryError.invalidBounds {
49	            throw ContinuousRoundedRasterError.invalidSize
50	        } catch ContinuousRoundedGeometryError.unsupportedRadiusExtent {
51	            throw ContinuousRoundedRasterError.unsupportedGeometry
52	        }
53	        let segments = flatten(path)
54	        let sampleCount = width * height * 16
55	        guard segments.count == 0 || sampleCount <= maxSampleSegmentEvaluations / segments.count else {
56	            throw ContinuousRoundedRasterError.workLimitExceeded
57	        }
58	        let bytes = width * height * 4
59	        var output = [UInt8](repeating: 0, count: bytes)
60	        let samples: [(Double, Double)] = [(0.125, 0.125), (0.375, 0.125), (0.625, 0.125), (0.875, 0.125),
61	                                            (0.125, 0.375), (0.375, 0.375), (0.625, 0.375), (0.875, 0.375),
62	                                            (0.125, 0.625), (0.375, 0.625), (0.625, 0.625), (0.875, 0.625),
63	                                            (0.125, 0.875), (0.375, 0.875), (0.625, 0.875), (0.875, 0.875)]
64	        for y in 0..<height {
65	            for x in 0..<width {
66	                var fillHits = 0, strokeHits = 0
67	                for (sx, sy) in samples {
68	                    let point = (Double(x) + sx, Double(y) + sy)
69	                    if fillRGBA != nil && inside(point, segments: segments) { fillHits += 1 }
70	                    if strokeRGBA != nil && stroke > 0 && distanceSquared(point, segments: segments) <= halfStroke * halfStroke { strokeHits += 1 }
71	                }
72	                let fillCoverage = Double(fillHits) / 16
